import React, { useMemo, useState } from 'react';
import './App.css';

// Practice version of a reported take-home. The catalog, names and numbers are ours.
export type BatteryId = 'xl' | 'l' | 'm' | 's';

export interface Device {
  id: BatteryId | 'transformer';
  name: string;
  widthFt: number;
  energyMwh: number;
  costUsd: number;
}

export type Battery = Device & { id: BatteryId };

export const BATTERIES: Battery[] = [
  { id: 's', name: 'Battery S', widthFt: 10, energyMwh: 1, costUsd: 12000 },
  { id: 'm', name: 'Battery M', widthFt: 20, energyMwh: 2, costUsd: 48000 },
  { id: 'l', name: 'Battery L', widthFt: 30, energyMwh: 3, costUsd: 82000 },
  { id: 'xl', name: 'Battery XL', widthFt: 40, energyMwh: 4.2, costUsd: 125000 }
];

// A transformer is added automatically: one for every two batteries, rounded up.
export const TRANSFORMER: Device = { id: 'transformer', name: 'Transformer', widthFt: 10, energyMwh: -0.25, costUsd: 9000 };

export const SITE_WIDTH_FT = 100;
export const ROW_DEPTH_FT = 10;
export const MAX_QUANTITY = 50;

type Quantities = Record<BatteryId, string>;

const EMPTY_QUANTITIES: Quantities = { xl: '0', l: '0', m: '0', s: '0' };

function formatUsd(value: number): string {
  return '$' + value.toLocaleString('en-US');
}

function formatMwh(value: number): string {
  return `${Number(value.toFixed(2))} MWh`;
}

function parseQuantity(raw: string): number | null {
  const text = raw.trim();
  if (!/^\d+$/.test(text)) return null;
  const value = Number(text);
  return value <= MAX_QUANTITY ? value : null;
}

export function transformersFor(batteryCount: number): number {
  return Math.ceil(batteryCount / 2);
}

type Row = { widthFt: number; devices: Device[] };

export function packRows(devices: Device[], maxWidthFt: number = SITE_WIDTH_FT): Row[] {
  const largestFirst = [...devices].sort((a, b) => b.widthFt - a.widthFt);
  const rows: Row[] = [];
  for (const device of largestFirst) {
    const row = rows.find((candidate) => candidate.widthFt + device.widthFt <= maxWidthFt);
    if (row) {
      row.widthFt += device.widthFt;
      row.devices.push(device);
    } else {
      rows.push({ widthFt: device.widthFt, devices: [device] });
    }
  }
  return rows;
}

export default function App() {
  const [quantities, setQuantities] = useState<Quantities>(EMPTY_QUANTITIES);

  const site = useMemo(() => {
    const invalid = BATTERIES.filter((battery) => parseQuantity(quantities[battery.id]) === null).map((battery) => battery.id);
    const devices: Device[] = [];
    for (const battery of BATTERIES) {
      const count = parseQuantity(quantities[battery.id]) ?? 0;
      for (let i = 0; i < count; i += 1) devices.push(battery);
    }
    const transformers = transformersFor(devices.length);
    for (let i = 0; i < transformers; i += 1) devices.push(TRANSFORMER);

    const costUsd = devices.reduce((sum, device) => sum + device.costUsd, 0);
    const energyMwh = devices.reduce((sum, device) => sum + device.energyMwh, 0);
    const rows = packRows(devices);
    const widthFt = rows.reduce((widest, row) => Math.max(widest, row.widthFt), 0);
    const depthFt = rows.length * ROW_DEPTH_FT;
    return { invalid, transformers, costUsd, energyMwh, rows, widthFt, depthFt };
  }, [quantities]);

  return (
    <main className="main">
      <section className="card">
        <header className="header">
          <h1 className="title">Battery Site Planner (Solution)</h1>
          <p className="subtitle">Choose the batteries; the planner adds transformers, totals the site and lays it out.</p>
        </header>

        <section className="panel" aria-labelledby="devices-title">
          <h2 className="panel-title" id="devices-title">Batteries</h2>
          {BATTERIES.map((battery) => (
            <label key={battery.id} className="qty-field">
              <span className="qty-name">{battery.name}</span>
              <span className="qty-meta">{battery.widthFt} ft · {battery.energyMwh} MWh · {formatUsd(battery.costUsd)}</span>
              <input
                className="qty-input"
                data-device={battery.id}
                type="number"
                min={0}
                max={MAX_QUANTITY}
                step={1}
                value={quantities[battery.id]}
                onChange={(event: React.ChangeEvent<HTMLInputElement>) =>
                  setQuantities((current) => ({ ...current, [battery.id]: event.target.value }))
                }
              />
            </label>
          ))}
          {site.invalid.length > 0 && (
            <p className="qty-error" role="alert">Use a whole number from 0 to {MAX_QUANTITY}.</p>
          )}
          <button type="button" className="reset" onClick={() => setQuantities(EMPTY_QUANTITIES)}>Reset</button>
        </section>

        <section className="panel" aria-labelledby="summary-title">
          <h2 className="panel-title" id="summary-title">Site summary</h2>
          <dl className="summary">
            <dt>Budget</dt>
            <dd className="total-cost">{formatUsd(site.costUsd)}</dd>
            <dt>Net energy</dt>
            <dd className="total-energy">{formatMwh(site.energyMwh)}</dd>
            <dt>Land</dt>
            <dd className="land-size">{site.widthFt} ft × {site.depthFt} ft</dd>
          </dl>
          <p className="transformer-count">Transformers: {site.transformers}</p>
        </section>

        <section className="panel" aria-labelledby="layout-title">
          <h2 className="panel-title" id="layout-title">Layout (100 ft wide)</h2>
          <div className="layout">
            {site.rows.map((row, rowIndex) => (
              <div key={rowIndex} className="layout-row" data-width={row.widthFt}>
                {row.devices.map((device, deviceIndex) => (
                  <div
                    key={deviceIndex}
                    className="layout-device"
                    data-device={device.id}
                    style={{ width: `${(device.widthFt / SITE_WIDTH_FT) * 100}%` }}
                    title={device.name}
                  >
                    {device.id === 'transformer' ? 'T' : device.id.toUpperCase()}
                  </div>
                ))}
              </div>
            ))}
          </div>
        </section>
      </section>
    </main>
  );
}

