:root {
  color-scheme: dark;
}

html, body {
  margin: 0;
  height: 100%;
  background: #020617;
  font-family: system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
}

.main {
  min-height: 100vh;
  background: #020617;
  color: #e5e7eb;
  display: grid;
  place-items: center;
  padding: 24px;
}

.card {
  width: 100%;
  max-width: 720px;
  background: #020617;
  border-radius: 16px;
  border: 1px solid #1f2937;
  padding: 18px 18px 16px;
  display: grid;
  gap: 16px;
}

.header {
  display: grid;
  gap: 4px;
}

.title {
  margin: 0;
  font-size: 20px;
  font-weight: 700;
}

.subtitle {
  margin: 0;
  font-size: 13px;
  color: #9ca3af;
}

.panel {
  display: grid;
  gap: 10px;
  padding: 12px;
  border-radius: 12px;
  border: 1px solid #1f2937;
}

.panel-title {
  margin: 0;
  font-size: 14px;
  font-weight: 600;
}

.qty-field {
  display: grid;
  grid-template-columns: 1fr auto 80px;
  gap: 8px;
  align-items: center;
  font-size: 14px;
}

.qty-meta {
  font-size: 12px;
  color: #9ca3af;
}

.qty-input {
  width: 100%;
  box-sizing: border-box;
  border-radius: 8px;
  border: 1px solid #374151;
  background: #020617;
  color: #e5e7eb;
  padding: 6px 8px;
  font-size: 14px;
}

.qty-input:focus {
  outline: none;
  border-color: #a3e635;
  box-shadow: 0 0 0 1px #a3e63533;
}

.qty-error {
  margin: 0;
  font-size: 13px;
  color: #f97316;
}

.reset {
  justify-self: start;
  border-radius: 999px;
  border: 1px solid #a3e635;
  background: transparent;
  color: #a3e635;
  padding: 6px 14px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
}

.summary {
  margin: 0;
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 4px 12px;
  font-size: 14px;
}

.summary dt {
  color: #9ca3af;
}

.summary dd {
  margin: 0;
  font-weight: 600;
}

.transformer-count {
  margin: 0;
  font-size: 13px;
  color: #9ca3af;
}

.layout {
  display: grid;
  gap: 4px;
}

.layout-row {
  display: flex;
  gap: 0;
  min-height: 28px;
  border: 1px dashed #1f2937;
}

.layout-device {
  box-sizing: border-box;
  border: 1px solid #020617;
  background: #1a2e05;
  color: #d9f99d;
  font-size: 11px;
  font-weight: 700;
  display: grid;
  place-items: center;
}

.layout-device[data-device="transformer"] {
  background: #1f2937;
  color: #e5e7eb;
}
